package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class MoveGeometryChecks {
 private GameWorld battle(GameWorld.Skill m,float ex,float ey){GameWorld w=new GameWorld();w.enemies.clear();w.spikes.clear();w.blocks.clear();w.blocks.add(new GameWorld.Block(0,0,4500,112));w.invulnerable=100;TestWorlds.equip(w,m);w.setDropSeed(0);GameWorld.Enemy e=new GameWorld.Enemy(ex,ey,true);e.hp=e.maxHp=1000;e.timer=1000;w.enemies.add(e);return w;}
 private void cast(GameWorld w){assertTrue(w.trySkill(0));for(int i=0;i<45;i++)w.step(1f/60,0,false,false);}
 @Test public void lateMeleeReachesTargetsThatScratchCannot(){GameWorld early=battle(GameWorld.Skill.SCRATCH,330,112);cast(early);assertEquals(1000,early.enemies.get(0).hp);GameWorld late=battle(GameWorld.Skill.SLASH,330,112);cast(late);assertTrue(late.enemies.get(0).hp<1000);}
 @Test public void tmClawHasGreaterReachAndVerticalCoverage(){assertTrue(MoveGeometry.reach(GameWorld.Skill.DRAGON_CLAW)>MoveGeometry.reach(GameWorld.Skill.FANG));GameWorld.Enemy e=new GameWorld.Enemy(230,215,true);assertFalse(MoveGeometry.hits(GameWorld.Skill.SCRATCH,100,112,1,e));assertTrue(MoveGeometry.hits(GameWorld.Skill.SHADOW_CLAW,100,112,1,e));}
 @Test public void frontAndRadialAttacksDifferInActualCombat(){GameWorld front=battle(GameWorld.Skill.SCRATCH,0,112);cast(front);assertEquals(1000,front.enemies.get(0).hp);GameWorld area=battle(GameWorld.Skill.BODY_SLAM,0,112);cast(area);assertTrue(area.enemies.get(0).hp<1000);}
 @Test public void rangeIsMirroredAndEllipseRejectsCorners(){GameWorld.Enemy e=new GameWorld.Enemy(-100,112,true);assertTrue(MoveGeometry.hits(GameWorld.Skill.DRAGON_CLAW,100,112,-1,e));assertFalse(MoveGeometry.hits(GameWorld.Skill.DRAGON_CLAW,100,112,1,e));e.x=340;e.y=280;assertFalse(MoveGeometry.hits(GameWorld.Skill.OUTRAGE,100,112,1,e));}
 @Test public void projectilesUseDeclaredRangesAndLaterMovesAreWider(){for(GameWorld.Skill m:GameWorld.Skill.values())if(m.ranged()){GameWorld.SkillShot shot=new GameWorld.SkillShot(0,300,1,m,1);assertEquals(m.name,MoveGeometry.projectileRange(m),Math.abs(shot.vx)*shot.life,.01);assertTrue(shot.life>0);}assertTrue(MoveGeometry.projectileRange(GameWorld.Skill.FLAMETHROWER)>MoveGeometry.projectileRange(GameWorld.Skill.EMBER));assertTrue(SkillVisual.radius(GameWorld.Skill.HEAT_WAVE)>SkillVisual.radius(GameWorld.Skill.EMBER));}
 @Test public void flareBlitzHasLongerDashThanFlameCharge(){assertTrue(MoveGeometry.dashSpeed(GameWorld.Skill.FLARE_BLITZ)*MoveGeometry.dashDuration(GameWorld.Skill.FLARE_BLITZ)>MoveGeometry.dashSpeed(GameWorld.Skill.FLAME_CHARGE)*MoveGeometry.dashDuration(GameWorld.Skill.FLAME_CHARGE));}
 @Test public void allMovesKeepSourcePower() throws Exception {java.nio.file.Path file=java.nio.file.Paths.get("assets/moves/move-effects.json");if(!java.nio.file.Files.exists(file))file=java.nio.file.Paths.get("../assets/moves/move-effects.json");com.badlogic.gdx.utils.JsonValue root=new com.badlogic.gdx.utils.JsonReader().parse(new String(java.nio.file.Files.readAllBytes(file),java.nio.charset.StandardCharsets.UTF_8));java.util.Map<String,Integer> powers=new java.util.HashMap<>();for(com.badlogic.gdx.utils.JsonValue v:root){com.badlogic.gdx.utils.JsonValue power=v.get("power");powers.put(v.getString("name"),power==null||power.isNull()?0:power.asInt());}for(GameWorld.Skill m:GameWorld.Skill.values()){assertTrue(m.name,powers.containsKey(m.name));assertEquals(m.name,(int)powers.get(m.name),m.power);}}
 @Test public void speciesSpeedCannotChangeEnemyMovement(){GameWorld a=battle(GameWorld.Skill.SCRATCH,700,112),b=battle(GameWorld.Skill.SCRATCH,700,112);GameWorld.Enemy ea=new GameWorld.Enemy(700,112,false),eb=new GameWorld.Enemy(700,112,false);a.enemies.clear();b.enemies.clear();a.enemies.add(ea);b.enemies.add(eb);ea.species=PokemonStats.Species.RATTATA;ea.level=1;eb.species=PokemonStats.Species.MAGMAR;eb.level=80;ea.timer=eb.timer=1000;for(int i=0;i<45;i++){a.step(1f/60,0,false,false);b.step(1f/60,0,false,false);}assertEquals(ea.x,eb.x,.001);assertEquals(ea.vx,eb.vx,.001);}
}
